from solution import house_bowling


def test_all_zero():
    assert house_bowling([0] * 20) == 0


def test_single_strike_first():
    assert house_bowling([10] + [0] * 18) == 10


def test_frame9_strike_frame10_strike():
    # frames 1-8 zeros (16 rolls), frame 9 strike, frame 10 strike
    rolls = [0] * 16 + [10, 10]
    assert house_bowling(rolls) == 10 + 10 + 10


def test_frame9_strike_frame10_open():
    rolls = [0] * 16 + [10, 3, 4]
    assert house_bowling(rolls) == (10 + 3 + 4) + 7


def test_frame10_strike_no_bonus():
    rolls = [0] * 18 + [10]
    assert house_bowling(rolls) == 10


def test_frame10_spare_no_bonus():
    rolls = [0] * 18 + [4, 6]
    assert house_bowling(rolls) == 10


def test_all_strikes():
    rolls = [10] * 10
    # frames 1-8: 30 each = 240, frame 9: 20, frame 10: 10
    assert house_bowling(rolls) == 270


def test_all_spares():
    rolls = [5, 5] * 10
    # frames 1-9: 15 each = 135, frame 10: 10
    assert house_bowling(rolls) == 145


def test_frame8_strike_frame9_strike_frame10_strike():
    rolls = [0] * 14 + [10, 10, 10]
    # f8: 30, f9: 20, f10: 10
    assert house_bowling(rolls) == 60


def test_spare_in_frame9_then_strike():
    rolls = [0] * 16 + [5, 5, 10]
    assert house_bowling(rolls) == 20 + 10

